    step_value = 0;
    int_pending = false;
    reset_pending = false;
    test_mode = false;
    test_output = 0;

    // Initialize timer state
    last_update_time = 0;
    current_counter_value = 0xffffffff;
    timer_enabled = false;
    timer_expired = false;
}

